const html = $input.first().json.data;

// Match each search result block
const resultBlocks = [...html.matchAll(
  /<div class="result results_links[\s\S]*?<\/div>\s*<\/div>\s*<\/div>/g
)];

const results = [];

for (const block of resultBlocks) {
  const content = block[0];

  // Extract title
  const titleMatch = content.match(
    /<a[^>]*class="result__a"[^>]*>(.*?)<\/a>/s
  );

  // Extract URL
  const urlMatch = content.match(
    /<a[^>]*class="result__a"[^>]*href="([^"]+)"/
  );

  // Extract snippet
  const snippetMatch = content.match(
    /<a class="result__snippet"[^>]*>(.*?)<\/a>/s
  );

  const clean = (text = "") =>
    text
      .replace(/<[^>]+>/g, "")
      .replace(/&amp;/g, "&")
      .replace(/&#x27;/g, "'")
      .replace(/&quot;/g, '"')
      .replace(/\s+/g, " ")
      .trim();

  if (titleMatch && urlMatch) {
    results.push({
      json: {
        title: clean(titleMatch[1]),
        url: urlMatch[1],
        snippet: clean(snippetMatch?.[1] || "")
      }
    });
  }
}

return results;

const MAX_CHARS = 3000;

return items.map(item => {
  let article = item.json.data || "";

  // Keep only the first 3000 characters
  if (article.length > MAX_CHARS) {
    article = article.substring(0, MAX_CHARS);
  }

  return {
    json: {
      data: article
    }
  };
});

